import{_ as s,o as t,c as n,a3 as a}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Entités Home Assistant","description":"","frontmatter":{"title":"Entités Home Assistant"},"headers":[],"relativePath":"fr/projects/blocks-for-ha/entities.md","filePath":"fr/projects/blocks-for-ha/entities.md","lastUpdated":1793108161000}'),i={name:"fr/projects/blocks-for-ha/entities.md"};function r(o,e,l,c,p,u){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="entites-home-assistant" tabindex="-1">Entités Home Assistant <a class="header-anchor" href="#entites-home-assistant" aria-label="Permalink to &quot;Entités Home Assistant&quot;">​</a></h1><p>Depuis <strong>0.1.44</strong>, les champs appropriés des blocs simples et avancés ouvrent une sélection avec recherche. Une petite flèche les signale. <strong>HA-Auswahl laden</strong> et <strong>Neu laden</strong> actualisent les catalogues en lecture seule. Les actions viennent de HA ; les cibles suivent <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> ou <code>label_id</code> : entités, appareils, zones, étages ou étiquettes. Les quatre derniers catalogues ne sont pas filtrés par action.</p><p><strong>Mehrere Ziele auswählen</strong> permet plusieurs cibles dans les champs prenant en charge les listes. IDs manuels, listes JSON et modèles Jinja pris en charge restent disponibles, y compris le texte multiligne intégral. Changer le type de cible ne réécrit pas les IDs existants. Sans catalogue d’actions, les exemples courants sont explicitement signalés ; les catalogues indisponibles permettent la saisie manuelle. Les menus spécialisés sont conservés. Noms de variables, IDs de déclencheurs, attributs, texte libre et données complexes ne reçoivent pas de sélection HA générique.</p><p>Installer <strong>0.1.44</strong> puis redémarrer l’application. Le serveur lit les entités et actions via l’<a href="https://developers.home-assistant.io/docs/api/rest/" target="_blank" rel="noreferrer">API REST</a> et les registres de cibles via l’<a href="https://developers.home-assistant.io/docs/api/websocket/" target="_blank" rel="noreferrer">API WebSocket</a>. Les permissions manquantes affectent seulement la liste concernée. Aucun jeton HA n’est envoyé au navigateur. La connexion et le nombre d’entités apparaissent dans la barre des réglages.</p><p>Cliquer sur un champ d’entité d’un bloc ouvre le sélecteur. Chercher par nom ou ID puis choisir une ligne. Les noms affichés viennent de votre installation et ne sont pas traduits. Les mots de recherche peuvent correspondre au nom ou à l’ID. Le choix remplit le champ actuellement modifié.</p><p>Le filtre suit le type du bloc : une lampe pour une action de couleur, un script pour un appel de script, le domaine approprié pour un assistant. Les actions génériques peuvent avoir une cible vide si leur service le permet. Les autres IDs doivent respecter <code>domaine.identifiant</code>.</p><p>La saisie manuelle reste possible, y compris hors HA. En cas de connexion indisponible, aucun état d’entité simulé n’est présenté comme une connexion réelle. Le chargement est une lecture : il n’exécute pas l’automatisation et n’écrit pas dans HA.</p><p>Les blocs standard avec sélecteur d’entité et les paquets personnalisés déclarant un champ <code>entity</code> utilisent ce mécanisme. La liste contient uniquement les informations publiques utiles à l’éditeur, sans attributs arbitraires ou jetons. Ne pas coller de secrets dans les champs de données ou projets.</p><p>Installer une fois la dépendance avec <code>python -m pip install --require-hashes -r requirements.txt</code>, puis lancer le service local avec <code>npm run entities</code>. Docker installe automatiquement la dépendance. Les 163 types de blocs, filtres, cinq types de cibles, listes et Jinja sont vérifiés automatiquement. Les tests serveur utilisent des réponses HA simulées ; vérifier ensuite l’exécution dans Home Assistant.</p><p><a href="./blocks">Catalogue des blocs</a> · <a href="https://developers.home-assistant.io/docs/add-ons/presentation/#ingress" target="_blank" rel="noreferrer">Documentation Ingress HA</a>.</p>',10)])])}const h=s(i,[["render",r]]);export{m as __pageData,h as default};
